export const ASSISTANT_URL='https://nysasoft.io/api/ledger-assistant';
export const QUESTIONS=[['Importar XML','¿Cómo importo y clasifico mis XML?'],['Revisar el mes','¿Cómo reviso ingresos, gastos y retenciones del mes?'],['Entender un cobro','¿Por qué un cobro puede ser menor que la factura?']];
export function conversationPayload(prompt,history){return {prompt:prompt.trim().slice(0,1000),language:'es',history:history.slice(-4).map(({role,content})=>({role,content:content.slice(0,1200)}))};}
export function mountNysaAssistant({navigate}){
 const host=document.createElement('div');host.className='nysa-assistant';
 host.innerHTML=`<section class="nysa-chat" id="nysa-chat" role="dialog" aria-labelledby="nysa-title" hidden>
 <header class="nysa-chat-head"><div><h2 id="nysa-title"><span aria-hidden="true">✧</span> Nysa <span>assist</span></h2><p class="nysa-status" role="status">Tu guía en NysaLedger</p></div><div class="nysa-head-tools"><button type="button" data-nysa="reset" aria-label="Nueva conversación" title="Nueva conversación">↺</button><button type="button" data-nysa="close" aria-label="Cerrar Nysa">×</button></div></header>
 <div class="nysa-chat-body"><div class="nysa-welcome"><p class="nysa-kicker">EN TU ÓRBITA</p><h3>Tus comprobantes, más claros.</h3><p>Te ayudo a importar XML, entender retenciones y revisar tu mes.</p><div class="nysa-suggestions">${QUESTIONS.map(([label],i)=>`<button type="button" data-question="${i}">${label} ↗</button>`).join('')}</div><div class="nysa-shortcuts"><button type="button" data-navigate="documents">Abrir comprobantes ↗</button><button type="button" data-navigate="summary">Ver resumen mensual ↗</button></div></div><div class="nysa-messages" role="log" aria-label="Conversación con Nysa" aria-live="polite" aria-relevant="additions"></div></div>
 <form class="nysa-composer"><div class="nysa-input-label"><label for="nysa-question">Tu consulta</label><span id="nysa-count">0 / 1000</span></div><div class="nysa-input-box"><textarea id="nysa-question" rows="2" maxlength="1000" placeholder="Ej.: ¿cómo reviso las retenciones?" aria-describedby="nysa-privacy nysa-count"></textarea><button type="submit" aria-label="Enviar consulta" disabled>↗</button></div><p id="nysa-privacy">Al enviar, tu consulta y los últimos mensajes se comparten con la IA de Nysasoft (Gemini). No se adjuntan tus XML ni datos de compañías.</p><p class="nysa-disclaimer">Guía de apoyo. No modifica datos ni presenta declaraciones.</p></form></section>
 <button type="button" class="nysa-launcher" aria-expanded="false" aria-controls="nysa-chat"><span aria-hidden="true">✧</span> Nysa</button>`;
 document.body.append(host);
 const panel=host.querySelector('.nysa-chat'),launcher=host.querySelector('.nysa-launcher'),input=host.querySelector('textarea'),form=host.querySelector('form'),send=form.querySelector('[type=submit]'),log=host.querySelector('[role=log]'),status=host.querySelector('.nysa-status'),body=host.querySelector('.nysa-chat-body'),welcome=host.querySelector('.nysa-welcome');
 let history=[],controller=null,pending=false,statusController=null,opened=false,closingAnimation=null;
 function resize(){const height=input.getBoundingClientRect().height;input.style.height='auto';const target=Math.min(180,Math.max(62,input.scrollHeight));input.style.height=height+'px';void input.offsetHeight;input.style.height=target+'px';input.style.overflowY=input.scrollHeight>180?'auto':'hidden';}
 function sync(){send.disabled=pending||!input.value.trim()||!navigator.onLine;host.querySelector('#nysa-count').textContent=input.value.length+' / 1000';}
 function message(role,text){const el=document.createElement('div');el.className='nysa-message nysa-message-'+role;const label=document.createElement('strong');label.textContent=role==='user'?'Tú':'✧ Nysa';const content=document.createElement('p');content.textContent=text;el.append(label,content);log.append(el);body.scrollTop=body.scrollHeight;return content;}
 function stop(){panel.removeAttribute('aria-busy');controller?.abort();controller=null;pending=false;sync();}
 function reset(){stop();panel.removeAttribute('aria-busy');history=[];log.replaceChildren();welcome.hidden=false;input.value='';resize();sync();}
 async function checkStatus(){statusController?.abort();statusController=new AbortController();status.textContent=navigator.onLine?'Conectando con Nysa…':'Sin conexión · abre Cómo funciona para la guía local';if(!navigator.onLine)return;try{const res=await fetch(ASSISTANT_URL,{credentials:'omit',signal:AbortSignal.any([statusController.signal,AbortSignal.timeout(8000)])});const data=await res.json();if(opened)status.textContent=res.ok&&data.enabled?'IA disponible · NysaLedger':'IA no disponible por ahora';}catch{if(opened)status.textContent='No se pudo conectar · puedes reintentar';}}
 function open(){closingAnimation?.cancel();opened=true;panel.hidden=false;launcher.setAttribute('aria-expanded','true');if(!matchMedia('(prefers-reduced-motion: reduce)').matches)panel.animate([{opacity:0,transform:'translateY(12px) scale(.98)'},{opacity:1,transform:'none'}],{duration:240,easing:'cubic-bezier(.2,.8,.2,1)'});input.focus({preventScroll:true});resize();sync();checkStatus();}
 function close(){if(!opened)return;opened=false;stop();statusController?.abort();launcher.setAttribute('aria-expanded','false');launcher.focus({preventScroll:true});if(matchMedia('(prefers-reduced-motion: reduce)').matches){panel.hidden=true;return;}closingAnimation=panel.animate([{opacity:1,transform:'none'},{opacity:0,transform:'translateY(8px)'}],{duration:160,easing:'ease-in'});closingAnimation.onfinish=()=>{if(!opened)panel.hidden=true;};}
 launcher.addEventListener('click',()=>opened?close():open());
 host.addEventListener('click',e=>{const target=e.target.closest('button');if(!target)return;if(target.dataset.nysa==='close')close();if(target.dataset.nysa==='reset'){reset();input.focus();checkStatus();}if(target.dataset.question!==undefined){input.value=QUESTIONS[Number(target.dataset.question)][1];resize();sync();input.focus();}if(target.dataset.navigate){close();navigate(target.dataset.navigate);document.querySelector('#main').focus({preventScroll:true});}});
 input.addEventListener('input',()=>{resize();sync();});
 host.addEventListener('keydown',e=>{if(e.key==='Escape'&&opened){e.stopPropagation();close();}});
 window.addEventListener('online',()=>{sync();if(opened)checkStatus();});window.addEventListener('offline',()=>{sync();if(opened)checkStatus();});
 form.addEventListener('submit',async e=>{e.preventDefault();if(pending||!input.value.trim()||!navigator.onLine)return;const prompt=input.value.trim();const payload=conversationPayload(prompt,history);message('user',prompt);welcome.hidden=true;input.value='';resize();pending=true;sync();panel.setAttribute('aria-busy','true');const reply=message('assistant','Pensando…');const requestController=new AbortController();controller=requestController;const timer=setTimeout(()=>requestController.abort('timeout'),38000);
 try{const response=await fetch(ASSISTANT_URL,{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',body:JSON.stringify(payload),signal:requestController.signal});const data=await response.json();if(!response.ok)throw Error(response.status===429?'RATE_LIMITED':data.error||'UNAVAILABLE');if(typeof data.reply!=='string'||!data.reply.trim())throw Error('EMPTY');if(requestController.signal.aborted)return;reply.textContent=data.reply;history.push({role:'user',content:prompt},{role:'assistant',content:data.reply});history=history.slice(-4);status.textContent='IA disponible · NysaLedger';}
 catch(error){if(requestController.signal.aborted&&requestController.signal.reason!=='timeout'){reply.textContent='Consulta cancelada. Puedes volver a enviarla.';}else{reply.textContent=error.message==='RATE_LIMITED'?'Hay varias consultas seguidas. Espera un minuto y vuelve a intentar.':'Nysa no pudo responder ahora. Tu consulta se conserva para reintentar. También puedes abrir Cómo funciona para consultar la guía local.';if(!input.value){input.value=prompt;resize();}}}
 finally{clearTimeout(timer);if(controller===requestController){controller=null;pending=false;panel.removeAttribute('aria-busy');sync();}body.scrollTop=body.scrollHeight;}
 });
 sync();return {reset,busy:()=>pending||Boolean(input.value.trim())};
}
